import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv from 'ajv';

const schemaValidator = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

interface CompiledSchema {
  (input: unknown): boolean;
  errors?: Array<{instancePath?: string; schemaPath?: string; keyword: string; params: Record<string, unknown>}> | null;
}

function pathFromSchemaPath(schemaPath = ''): string {
  const segments = schemaPath.split('/');
  const properties: string[] = [];
  for (let index = 0; index < segments.length - 1; index += 1) {
    if (segments[index] === 'properties') {
      properties.push((segments[index + 1] ?? '').replace(/~1/g, '/').replace(/~0/g, '~'));
    }
  }
  return properties.length ? `/${properties.join('/')}` : '';
}

function describeValidationError(error: NonNullable<CompiledSchema['errors']>[number]): string {
  const path = error.instancePath || pathFromSchemaPath(error.schemaPath) || '/';
  if (error.keyword === 'required') {
    const missingProperty = String(error.params['missingProperty']).replace(/~/g, '~0').replace(/\//g, '~1');
    return `Missing required property: ${path === '/' ? '' : path}/${missingProperty}`;
  }
  if (error.keyword === 'type') return `Property ${path} must be of type ${String(error.params['type'])}`;
  if (error.keyword === 'enum') return `Property ${path} must be one of the allowed values`;
  return `Input does not satisfy the schema at ${path}`;
}

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: CompiledSchema;
  validators: WeakMap<object, CompiledSchema>;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private getValidator(tool: StoredTool, schema: object): CompiledSchema {
    const cached = tool.validators.get(schema);
    if (cached) return cached;
    const validate = schemaValidator.compile(schema) as CompiledSchema;
    tool.validators.set(schema, validate);
    return validate;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let staticValidator: CompiledSchema | undefined;
    if (typeof definition !== 'function') {
      try {
        staticValidator = schemaValidator.compile(resolved.inputSchema) as CompiledSchema;
      } catch (error) {
        throw new Error(
          `Invalid inputSchema for tool ${resolved.name}: ${error instanceof Error ? error.message : String(error)}`,
          {cause: error}
        );
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator, validators: new WeakMap()});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input per specs/hal-engine-tool-input-validation/spec.md; rejects return a ToolResponse, unknown names throw. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = tool.staticValidator ?? this.getValidator(tool, definition.inputSchema as object);
    if (!validate(input)) {
      const error = validate.errors?.[0];
      return {result: error ? describeValidationError(error) : 'Input does not satisfy the schema'};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('returns a rejection for a missing required property without calling the executor [specs/hal-engine-tool-input-validation/spec.md#3]', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {name: 'weather', description: '', inputSchema: {type: 'object', required: ['location']}},
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );
    const result = await registry.execute('weather', {});
    expect({
      resultNamesRequiredLocation: /location.*required|required.*location/i.test(result.result),
      executorCalls,
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  it('names the property path and expected type for a wrong-typed value [specs/hal-engine-tool-input-validation/spec.md#4]', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: '',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const result = await registry.execute('weather', {location: 123});

    expect({
      namesPathAndType: /\/location.*string|string.*\/location/i.test(result.result),
      leaksValue: result.result.includes('123'),
      executorCalls,
    }).toEqual({namesPathAndType: true, leaksValue: false, executorCalls: 0});
  });

  it('passes a valid input and undeclared properties through unchanged [specs/hal-engine-tool-input-validation/spec.md#5]', async () => {
    const registry = new ToolRegistry();
    let received: Record<string, unknown> | undefined;
    registry.register(
      {name: 'weather', description: '', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}},
      async input => {
        received = input;
        return 'sunny';
      }
    );
    const input = {location: 'Berlin', extra: true};

    await registry.execute('weather', input);

    expect(received).toEqual(input);
  });

  it('includes the parent path when a nested required property is missing [specs/hal-engine-tool-input-validation/spec.md#3]', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: '',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'object', required: ['city']}},
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const result = await registry.execute('weather', {location: {}});

    expect(result.result).toContain('/location/city');
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required, including its parent path when nested, and never invokes the executor. ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [validated by: returns a rejection for a missing required property without calling the executor](../../src/orchestration/tools/registry.test.ts#L4), [validated by: includes the parent path when a nested required property is missing](../../src/orchestration/tools/registry.test.ts#L62))
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value. ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by: names the property path and expected type for a wrong-typed value](../../src/orchestration/tools/registry.test.ts#L21))
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults. ([validated by: passes a valid input and undeclared properties through unchanged](../../src/orchestration/tools/registry.test.ts#L45))
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static schema that cannot be compiled makes registration fail synchronously and names the tool. ([validated by: rejects an invalid static schema during registration](../../src/orchestration/tools/registry.registration.test.ts#L4))
- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

